draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // simple pleasures
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // book
  ctx.beginPath();
  ctx.rect(W/2 - 20, H/2 - 50 + 20*Math.sin(t), 40, 60);
  ctx.stroke();

  // wine cup
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 20 + 20*Math.cos(t), 20, 0, 2*Math.PI);
  ctx.stroke();

  // garden
  ctx.beginPath();
  ctx.arc(W/2 - 80, H/2 + 20, 30 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 90);
  ctx.lineTo(W/2 - 20, H/2 + 110);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 90);
  ctx.lineTo(W/2 + 20, H/2 + 110);
  ctx.stroke();

  ctx.restore();
}
